export function setDistribution(id) {
  const d = distById(id);
  if (!d) return { error: 'Unknown deal.' };
  if (state.tier < d.minTier) return { error: `${d.name} unlocks at ${TIERS[d.minTier].name}.` };
  if (state.dist === id) return { error: 'Already on this deal.' };
