export const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const money = (n) => fmtMoney(n);
const num = (n) => fmtNum(n);
const pct = (n) => `${Math.round(n)}%`;
