  if (!n || Math.abs(n) < 0.5) return `<span class="dim">${suffix} flat</span>`;
  return `<span class="${n > 0 ? 'green' : 'red'}">${n > 0 ? '▲' : '▼'} ${num(Math.abs(n))}${suffix}</span>`;
};

