207: export function makeArtist(opts = {}) {
208:   const genre = opts.genre || pick(GENRES).id;
209:   const tier = opts.tier ?? 0;
210:   const popBase = opts.popularity ?? (randi(8, 22) + tier * randi(4, 10));
211:   const popularity = clamp(popBase, 2, 96);
212:   const trait = opts.trait ? traitById(opts.trait) : pick(TRAITS);
213:   const skillBase = 34 + tier * 4 + rand(0, 30);
214:   const ego = clamp(rand(10, 60) + (trait.ego || 0) + popularity * 0.25, 5, 98);
215:   const salary = Math.round((480 + popularity * 52 + rand(0, 400)) * (1 + (trait.salary || 0)) / 10) * 10;
216:   const a = {
217:     id: uid('art'),
218:     name: opts.name || freshArtistName(),
219:     genre,
220:     age: randi(19, 38),
221:     popularity,
222:     skill: clamp(skillBase + (trait.quality || 0) * 0.7, 25, 96),
223:     songwriting: clamp(skillBase + rand(-8, 14), 20, 97),
224:     charisma: clamp(34 + rand(0, 42) + (trait.commercial || 0) * 0.8, 20, 98),
225:     workEthic: clamp(rand(35, 92) + (trait.growth ? 8 : 0), 20, 99),
226:     ego,
227:     loyalty: clamp(rand(38, 78) + (trait.loyalty || 0), 10, 98),
228:     morale: randi(62, 82),
229:     fans: Math.round(popularity ** 2 * rand(180, 420)),
230:     salary,
231:     trait: trait.id,
232:     avatar: makeAvatar(),
233:     labelId: opts.labelId || null,
234:     labelName: opts.labelName || null,
235:     contract: opts.contract || null,
236:     signedWeek: opts.signedWeek || null,
237:     busyUntil: 0,
238:     status: 'active',
239:     scouted: !!opts.scouted,
240:     totalStreams: 0,
241:     hits: 0,
242:     top10: 0,
243:     careerWeeks: 0,
244:     royaltyDemand: clamp(0.12 + popularity / 700 + rand(0, 0.06), 0.1, 0.3),
245:     advanceDemand: Math.round((salary * 6 + popularity * 250) / 100) * 100,
246:     createdWeek: opts.week || 0,
247:   };
248:   a.popularity = clamp(popularity + (GENRE_POP_BIAS[genre] || 0) * 0.3, 2, 96);
249:   a.fans = Math.round(a.popularity ** 2 * rand(180, 420));
250:   return a;
251: }
