253: export function makeProspect(tier = 0, week = 1) {
254:   const r = Math.random();
255:   let pop;
256:   if (r < 0.5) pop = rand(4, 18) + tier * 2;
257:   else if (r < 0.82) pop = rand(18, 38) + tier * 3;
258:   else pop = rand(38, 58) + tier * 4;
259:   const a = makeArtist({ popularity: pop, tier: Math.max(0, tier - 1), week });
260:   a.scouted = false;
261:   a.labelId = null;
262:   a.labelName = null;
263:   a.contract = null;
264:   a.status = 'free';
265:   return a;
266: }
