285: export function previewSong(o = {}) {
286:   const artist = findRosterArtist(o.artistId) || {};
287:   if (!artist.id) return null;
288:   const producer = staffSkill('producer', o.producerId);
289:   const writer = staffSkill('songwriter', o.writerId);
290:   const feature = o.featureId && o.featureId !== 'none' ? findRosterArtist(o.featureId) : null;
291:   const studio = state.studios.find((s) => s.id === o.studioId) || state.studios[0];
292:   const b = BUDGETS[o.budget] || BUDGETS.standard;
293:   const f = FOCUS[o.focus] || FOCUS.balanced;
294:   const trait = traitById(artist.trait) || {};
295:   const genre = o.genre || artist.genre;
296:   const trend = state.trends[genre] || 1;
297:   const producerSkillVal = producer ? producer.skill : artist.skill * 0.65;
298:   const writerSkillVal = writer ? writer.skill : artist.songwriting;
299:   const studioQ = studioQuality(studio?.id);
300:   const genreMatch = artist.genre === genre ? 1 : 0;
301:   let quality = 18 + artist.skill * 0.26 + writerSkillVal * 0.19 + producerSkillVal * 0.2
302:     + (studioQ - 20) * 0.13 + b.quality * 0.7 + (trait.quality || 0) + f.quality
303:     + genreMatch * 4 + (feature ? (feature.skill - 50) * 0.08 + 1.5 : 0);
304:   let commercial = 15 + artist.charisma * 0.32 + quality * 0.22 + (trend - 1) * 26 + f.commercial
305:     + (trait.commercial || 0) + genreMatch * 2 + (feature ? feature.charisma * 0.08 : 0);
306:   const featMod = (artist.popularity + (feature?.popularity || 0)) / 220;
307:   quality = clamp(quality + featMod * 3, 20, 99);
308:   commercial = clamp(commercial, 15, 99);
309:   const appeal = quality * 0.56 + commercial * 0.44;
310:   const peak = computePeak(appeal, artist.popularity, state.reputation, distById(state.dist).reach, 1, trend, false);
311:   const featureFee = feature ? Math.round(2500 + feature.popularity * 190) : 0;
312:   const legal = hasFacility('legal') ? 0.88 : 1;
313:   const cost = Math.round((b.cost + featureFee) * legal);
314:   return { quality: Math.round(quality), commercial: Math.round(commercial), appeal: Math.round(appeal), peak, cost, featureFee, studioQ: Math.round(studioQ) };
315: }
