317: export function computePeak(appeal, popularity, rep, distReach = 1, extra = 1, trend = 1, randomize = true) {
318:   const core = clamp((appeal - 18) / 82, 0, 1.12);
319:   const reach = (0.7 + rep / 100 * 0.9 + popularity / 100 * 1.02) * distReach;
320:   const noise = randomize ? rand(0.88, 1.12) : 1;
321:   return Math.max(20000, core * core * 3200000 * reach * trend * extra * noise);
322: }
