+}
+
+/* -------------------------------- festivals -------------------------------- */
+function festivalCreateModal(s) {
+  const loc = FESTIVAL_LOCATIONS.find((l) => s.reputation >= l.minRep) || FESTIVAL_LOCATIONS[0];
+  return modalShell({
+    title: 'Create a festival',
