const BASE = 'http://127.0.0.1:9222';
const APP = 'http://localhost:8123/index.html';

const list = await (await fetch(`${BASE}/json/list`)).json();
for (const t of list) if (t.type === 'page') await fetch(`${BASE}/json/close/${t.id}`);
await new Promise((r) => setTimeout(r, 400));
const target = await (await fetch(`${BASE}/json/new?${encodeURIComponent(APP)}`, { method: 'PUT' })).json();
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((r) => { ws.onopen = r; });
let id = 0; const pending = new Map(); const errors = [];
ws.onmessage = (ev) => {
  const m = JSON.parse(ev.data);
  if (m.id && pending.has(m.id)) { pending.get(m.id)(m.result); pending.delete(m.id); return; }
  if (m.method === 'Runtime.exceptionThrown') errors.push('EXC ' + (m.params.exceptionDetails?.exception?.description || m.params.exceptionDetails?.text || '').slice(0, 300));
  if (m.method === 'Runtime.consoleAPICalled' && m.params.type === 'error') errors.push('ERR ' + JSON.stringify(m.params.args?.[0]?.description || m.params.args?.[0]?.value || '').slice(0, 300));
  if (m.method === 'Log.entryAdded' && m.params.entry.level === 'error') errors.push('LOG ' + m.params.entry.text.slice(0, 300));
};
const send = (method, params = {}) => new Promise((res) => { const i = ++id; pending.set(i, res); ws.send(JSON.stringify({ id: i, method, params })); });
const ev = async (expression) => {
  const r = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true, userGesture: true });
  if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || r.exceptionDetails.text);
  return r.result?.value;
};
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const out = {};

await send('Page.enable'); await send('Runtime.enable'); await send('Log.enable'); await send('Page.bringToFront');
await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 980, deviceScaleFactor: 1, mobile: false });
await send('Page.reload', { ignoreCache: true });
await sleep(1800);

// Fresh game
await ev(`(async () => { const G = MusicEmpire.Game; G.clearSave(); localStorage.clear(); location.reload(); })()`);
await sleep(1800);
out.intro = await ev(`!!document.querySelector('.intro')`);
await ev(`(() => {
  const n = document.getElementById('intro-name'); if (n) { n.value = 'Aurora Sound'; n.dispatchEvent(new Event('input', { bubbles: true })); }
  const g = document.getElementById('intro-genre'); if (g) g.value = 'pop';
  document.querySelector('[data-act="intro-start"]').click();
})()`);
await sleep(800);
out.started = await ev(`(() => { const s = MusicEmpire.Game.getState(); return { label: s.label.name, week: s.week, cash: s.cash }; })()`);

// Fund and sign a roster
out.sign = await ev(`(() => {
  const G = MusicEmpire.Game; const s = G.getState(); s.cash = 8000000; s.reputation = 88; G.saveGame();
  const results = [];
  for (let i = 0; i < 6 && s.roster.length < 2; i++) { const p = s.prospects[i]; if (!p) break; const r = G.signArtist(p.id, 'standard'); results.push({ name: p.name, ok: !!r.ok, err: r.error || (r.rejected ? 'rejected' : null) }); }
  return { roster: s.roster.map(a => a.name), results };
})()`);

// Walk every screen
const screens = ['dashboard','roster','studio','charts','marketing','tours','industry','finance','company','calendar','legacy','awards','festivals'];
out.screens = {};
let errBase = errors.length;
for (const sc of screens) {
  await ev(`document.querySelector('[data-screen="${sc}"]').click()`);
  await sleep(700);
  out.screens[sc] = await ev(`({ title: document.querySelector('.page-title')?.textContent || null, canvases: document.querySelectorAll('canvas[data-scene]').length, cards: document.querySelectorAll('.card,.stat').length })`);
}
out.screenErrors = errors.slice(errBase);

// Roster: artist modal + career section + meeting
await ev(`document.querySelector('[data-screen="roster"]').click()`);
await sleep(500);
out.artistModalOpen = await ev(`(() => { const b = document.querySelector('[data-act="open-artist"]'); if (!b) return false; b.click(); return true; })()`);
await sleep(500);
out.artistModal = await ev(`({ title: document.querySelector('.modal-title')?.textContent, career: !!document.querySelector('.career-panel'), meetings: document.querySelectorAll('[data-act="artist-meeting"]').length, timeline: !!document.querySelector('.career-timeline') })`);
out.meeting = await ev(`(() => { const G = MusicEmpire.Game; const b = document.querySelector('[data-act="artist-meeting"][data-topic="vision"]'); const before = G.getState().roster[0].morale; b.click(); const after = G.getState().roster[0].morale; return { before, after, stillOpen: !!document.querySelector('.career-panel') }; })()`);
await sleep(400);
await ev(`document.querySelector('[data-act="close"]')?.click()`);
await sleep(300);

// Session book -> vault
out.session = await ev(`(() => { document.querySelector('[data-act="open-record"]')?.click(); return !!document.querySelector('#song-form'); })()`);
await sleep(500);
out.record = await ev(`(() => {
  const f = document.querySelector('#song-form'); if (!f) return { skipped: true };
  const btn = [...document.querySelectorAll('[data-act="record-song"]')][0];
  if (btn) btn.click();
  const s = MusicEmpire.Game.getState();
  return { demos: s.demos.length, cash: s.cash };
})()`);
await sleep(700);
await ev(`document.querySelector('[data-act="close"]')?.click()`);
await sleep(300);

// Advance 40 weeks with reveals, then to first awards at week 52
out.sim = await ev(`(async () => {
  const G = MusicEmpire.Game; const ui = await import('/js/ui.js');
  let events = 0, ceremonies = 0, guard = 0;
  while (G.getState().week < 52 && guard++ < 200) {
    if (G.currentEvent()) { G.resolveEvent(0); events++; continue; }
    if (G.getState().pendingCeremony) { ceremonies++; G.dismissCeremony(); continue; }
    if (G.getState().gameOver) break;
    const r = G.advanceWeek();
    if (r.error) { if (G.getState().pendingEvents.length) { G.resolveEvent(0); events++; } else break; }
    ui.render();
  }
  const s = G.getState();
  return { week: s.week, cash: s.cash, gameOver: s.gameOver, events, ceremonies, awards: s.awardsHistory.length, pending: !!s.pendingCeremony, collectibles: s.legacy.collectibles.length, releases: s.releases.length, tracks: s.tracks.length };
})()`);
await sleep(700);
out.ceremonyUi = await ev(`({ modal: !!document.querySelector('.ceremony-modal'), dismiss: !!document.querySelector('[data-act="dismiss-ceremony"]') })`);
await ev(`document.querySelector('[data-act="dismiss-ceremony"]')?.click()`);
await sleep(400);

// Awards page shows season
await ev(`document.querySelector('[data-screen="awards"]').click()`);
await sleep(800);
out.awardsPage = await ev(`({ cats: document.querySelectorAll('.award-category').length, seasons: document.querySelectorAll('.season-row').length, title: document.querySelector('.page-title')?.textContent })`);

// Festival lifecycle
out.festival = await ev(`(() => {
  const G = MusicEmpire.Game; const s = G.getState(); s.cash = 8000000; s.reputation = 90;
  const r = G.createFestival({ name: 'Aurora Fields', location: 'city', theme: 'neon', leadWeeks: 4, ticketPrice: 70, marketing: 50000 });
  if (r.error) return { error: r.error };
  const f = r.festival;
  const up = ['stages','vip','food','merch','backstage'].map(id => ({ id, r: G.upgradeFestival(f.id, id).error || 'ok' }));
  const artist = s.roster[0];
  const book = artist ? G.bookFestivalArtist(f.id, artist.id) : { error: 'no artist' };
  const sp = G.setFestivalSponsor(f.id, 'energy');
  G.updateFestival(f.id, { ticketPrice: 88 });
  return { id: f.id, week: f.week, upgrades: up, booked: book.error || book.artist?.name, sponsor: sp.error || G.getState().festivals.find(x=>x.id===f.id).sponsor, estimate: G.estimateFestival(G.getState().festivals.find(x=>x.id===f.id)) };
})()`);
await ev(`(async () => { const G = MusicEmpire.Game; const ui = await import('/js/ui.js'); const f = G.getState().festivals[0]; let guard = 0; while (G.getState().week < f.week && guard++ < 20) { if (G.currentEvent()) { G.resolveEvent(0); continue; } if (G.getState().pendingCeremony) { G.dismissCeremony(); continue; } G.advanceWeek(); } ui.render(); })()`);
await sleep(500);
out.festivalDone = await ev(`(() => { const G = MusicEmpire.Game; const s = G.getState(); const f = s.festivals[0]; return { status: f.status, attendance: f.attendance, satisfaction: f.satisfaction, revenue: f.revenue, costs: f.costs, profit: f.profit, posters: s.legacy.collectibles.filter(c => c.category === 'memorabilia' || c.defId === 'festival_poster').length, cash: s.cash }; })()`);
await ev(`document.querySelector('[data-screen="festivals"]').click()`);
await sleep(700);
out.festivalsPage = await ev(`({ cards: document.querySelectorAll('.festival-card').length, completed: [...document.querySelectorAll('.festival-card .pill')].map(e=>e.textContent).slice(0,6) })`);

// Save migration: strip expansion fields
out.migration = await ev(`(() => {
  const G = MusicEmpire.Game; const key = 'music-empire-save-v1';
  G.saveGame(); const raw = JSON.parse(localStorage.getItem(key));
  const had = { complex: !!raw.complex, legacy: !!raw.legacy, festivals: Array.isArray(raw.festivals), awards: Array.isArray(raw.awardsHistory) };
  delete raw.complex; delete raw.legacy; delete raw.festivals; delete raw.awardsHistory; delete raw.pendingCeremony;
  raw.roster = (raw.roster || []).map(a => { delete a.personality; delete a.ambitions; delete a.careerWeeks; delete a.relationships; return a; });
  localStorage.setItem(key, JSON.stringify(raw));
  return { had, bytes: JSON.stringify(raw).length };
})()`);
await send('Page.reload', { ignoreCache: true });
await sleep(1800);
out.afterReload = await ev(`(() => { const s = MusicEmpire.Game.getState(); return { label: s.label.name, week: s.week, complex: !!s.complex?.wings, legacy: Array.isArray(s.legacy?.collectibles), festivals: Array.isArray(s.festivals), awards: Array.isArray(s.awardsHistory), profile: s.roster[0] ? { personality: s.roster[0].personality, careerWeeks: s.roster[0].careerWeeks, ambition: s.roster[0].ambition } : null }; })()`);

// Legacy interactions
await ev(`document.querySelector('[data-screen="legacy"]').click()`);
await sleep(800);
out.legacy = await ev(`({ cards: document.querySelectorAll('.collectible-card').length, canvas: document.querySelectorAll('.scene-card canvas').length, certRows: document.querySelectorAll('.cert-row').length, stats: MusicEmpire.Game.legacyStats() })`);
await ev(`document.querySelector('[data-act="auto-display"]')?.click()`);
await sleep(500);
out.legacyDisplay = await ev(`(() => { const s = MusicEmpire.Game.getState(); return s.legacy.collectibles.filter(c => c.displayed).length; })()`);

// Mobile layouts
await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 1, mobile: true });
out.mobile = {};
