out.after=await ev(`(() => { const G=MusicEmpire.Game,s=G.getState(); const t=s.tracks.filter(t=>t.isPlayer); return {week:s.week, playerTracks:t.map(x=>({title:x.title,weekly:x.weekly,total:x.streamsTotal,peak:x.chartPeak})), collectibles:s.legacy.collectibles.map(c=>({n:c.name,r:c.rarity})), cash:s.cash}; })()`);
// Force certifications
out.cert=await ev(`(() => { const G=MusicEmpire.Game,s=G.getState(); const t=s.tracks.filter(x=>x.isPlayer)[0]; if(!t) return {skip:true}; t.streamsTotal=52000000; G.checkCertifications(); return s.legacy.collectibles.filter(c=>c.category==='certification').map(c=>c.defId); })()`);
