const BASE='http://127.0.0.1:9222';
const tabs=await (await fetch(`${BASE}/json/list`)).json();
const page=tabs.filter(t=>t.type==='page'&&t.url.includes('localhost:8123')).at(-1);
if(!page) throw new Error('Game tab not found');
const ws=new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve,reject)=>{ws.onopen=resolve;ws.onerror=reject});
let id=0; const pending=new Map(); const errors=[];
ws.onmessage=event=>{const message=JSON.parse(event.data);if(message.id&&pending.has(message.id)){pending.get(message.id)(message.result);pending.delete(message.id)}else if(message.method==='Runtime.exceptionThrown'){errors.push(message.params.exceptionDetails?.exception?.description||message.params.exceptionDetails?.text)}};
const send=(method,params={})=>new Promise(resolve=>{const requestId=++id;pending.set(requestId,resolve);ws.send(JSON.stringify({id:requestId,method,params}))});
const evaluate=async expression=>{const response=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true,userGesture:true});if(response.exceptionDetails)throw new Error(response.exceptionDetails.exception?.description||response.exceptionDetails.text);return response.result?.value};
const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));
await send('Runtime.enable'); await send('Page.enable');
const saved=await evaluate(`localStorage.getItem('music-empire-save-v1')`);
let results;
try {
  results=await evaluate(`(()=>{
    const G=MusicEmpire.Game, s=G.getState();
    s.cash=1500000; s.reputation=80; s.festivals=[]; s.pendingEvents=[]; s.pendingCeremony=null; s.gameOver=false;
    const artist=s.roster.find(a=>a.contract&&!a.retired);
    if(!artist) return {setupError:'No contracted roster artist available'};
    const created=G.createFestival({name:'Lifecycle QA',location:'fairground',theme:'indie',leadWeeks:3,ticketPrice:45,marketing:10000});
    if(created.error) return {createError:created.error};
    const f=created.festival, cashAfterCreate=s.cash;
    const booking=G.bookFestivalArtist(f.id,artist.id);
    if(booking.error) return {bookingError:booking.error};
    const quote=G.festivalBookingQuote(f,artist.id);
    const before={cash:s.cash,spent:f.spent,lineup:f.lineup.length,draw:G.festivalLineupDraw(f)};
    const upgrade=G.upgradeFestival(f.id,'stages');
    const upgradeOk=!upgrade.error;
    f.week=s.week+1;
    s.pendingEvents=[]; s.pendingCeremony=null;
    const step=G.advanceWeek();
    const after=G.festivalById(f.id);
    const artistAfter=s.roster.find(a=>a.id===artist.id);
    const completed={status:after.status,attendance:after.attendance,revenue:after.revenue,costs:after.costs,profit:after.profit,completedWeek:after.completedWeek,poster:s.legacy.collectibles.some(c=>c.category==='festival_poster'&&c.name.includes('Lifecycle QA')),artistPopularity:artistAfter.popularity,artistMorale:artistAfter.morale,week:s.week,stepError:step.error||null};
    return {artist:artist.name,created:{week:created.festival.week,cashAfterCreate},booking:{fee:quote.fee,...before},upgradeOk,completed,postCompletionBook:G.bookFestivalArtist(f.id,artist.id).error,postCompletionUpgrade:G.upgradeFestival(f.id,'stages').error};
  })()`);
} finally {
  const restore= saved===null ? `localStorage.removeItem('music-empire-save-v1')` : `localStorage.setItem('music-empire-save-v1',${JSON.stringify(saved)})`;
  await evaluate(restore);
  await send('Page.reload',{ignoreCache:true});
  await wait(1300);
}
console.log(JSON.stringify({results,errors},null,2));
ws.close();

