43:   const labelName = name?.trim() || 'Afterglow Records';
44:   const competitors = makeCompetitors(1);
45:   const tracks = [];
46:   // Seed the world with existing hits so the charts are alive from week one.
47:   for (const comp of competitors) {
48:     const seeds = randi(5, 8);
49:     for (let i = 0; i < seeds; i++) {
