64:     },
65:     cash: 150000,
66:     reputation: 6,
67:     tier: 0,
68:     dist: 'diy',
69:     studios: [{ id: uid('std'), name: 'Bedroom Studio', level: 0, equipment: [] }],
70:     complex: {
