72:       theme: 'midnight', floor: 'oak', lighting: 'warm',
73:     },
74:     legacy: { collectibles: [], trophyTheme: 'gold', layout: 'classic', prestige: 0 },
75:     festivals: [],
76:     awardsHistory: [],
77:     pendingCeremony: null,
78:     facilities: [],
79:     staff: [],
80:     roster: [],
81:     prospects: [],
