98:     pendingEvents: [],
99:     awards: [],
100:     loans: [],
101:     trends: Object.fromEntries(GENRES.map((g) => [g.id, 1])),
102:     trendState: { hot: 'pop', nextShift: randi(5, 8) },
103:     flags: { won: false, insolventWeeks: 0, studioMalusUntil: 0, releaseCount: 0 },
104:     news: [],
105:     gameOver: false,
106:     createdAt: Date.now(),
107:   };
108:   // starting prospects — a real audition pool
109:   for (let i = 0; i < 11; i++) s.prospects.push(makeProspect(0, 1));
110:   const hot = s.trendState.hot;
111:   s.trends[hot] = 1.12;
112:   s.news.unshift({ week: 1, kind: 'welcome', text: `${labelName} is officially open for business. ${fmtMoney(150000)} in the bank and everything to prove.` });
113:   s.news.unshift({ week: 1, kind: 'trend', text: `${genreById(hot).name} is the sound of the moment. Artists in the genre are drawing extra attention.` });
114:   state = s;
115:   // Give the seed catalog a plausible current week so charts are alive on day one.
116:   for (const t of s.tracks) {
117:     const age = Math.max(1, s.week - t.releaseWeek);
118:     t.weekly = t.peak * Math.pow(0.5, Math.max(0, age - 1) / t.halfLife) * rand(0.85, 1.15);
119:     t.lastWeekly = t.weekly;
120:     t.streamsTotal = t.weekly * age * 0.7;
121:   }
122:   computeCharts(true);
123:   saveGame();
124:   return s;
125: }
