231: export function studioQuality(studioId) {
232:   const st = state.studios.find((x) => x.id === studioId) || state.studios[0];
233:   if (!st) return 22;
234:   const lvl = STUDIO_LEVELS[st.level] || STUDIO_LEVELS[0];
235:   let q = lvl.base;
236:   for (const eqId of st.equipment || []) {
237:     const eq = EQUIPMENT.find((e) => e.id === eqId);
238:     if (eq) q += eq.quality;
239:   }
240:   const engineers = state.staff.filter((s) => s.role === 'engineer');
241:   if (engineers.length) q += Math.max(...engineers.map((e) => e.skill)) * 0.12;
242:   if (state.flags.studioMalusUntil > state.week) q -= 3;
243:   if (state.facilities.includes('marketing')) q += 1;
244:   q += complexBonuses().quality * 0.6;
245:   return clamp(q, 8, 125);
246: }
247: export const studioLevelInfo = (level) => STUDIO_LEVELS[level] || STUDIO_LEVELS[0];
248: export const studioUpgradeCost = (st) => st.level >= STUDIO_LEVELS.length - 1 ? null : STUDIO_LEVELS[st.level + 1].cost;
249: export const newStudioCost = () => 180000 * (state.studios.length ** 1.4);
