251: export function weeklyRecurring() {
252:   const items = [];
253:   const dist = distById(state.dist);
254:   if (dist.weekly) items.push({ label: 'Distribution', amount: dist.weekly, cat: 'distribution' });
255:   for (const st of state.studios) {
256:     const lvl = studioLevelInfo(st.level);
257:     items.push({ label: `${st.name} upkeep`, amount: lvl.upkeep, cat: 'studio' });
258:   }
259:   for (const f of state.facilities) {
260:     const def = facilityById(f);
261:     if (def) items.push({ label: def.name, amount: def.upkeep, cat: 'facilities' });
262:   }
263:   for (const s of state.staff) items.push({ label: `${s.name} · ${s.role}`, amount: s.salary, cat: 'staff' });
264:   for (const a of state.roster) {
265:     if (a.contract) items.push({ label: `${a.name} salary`, amount: a.contract.salary, cat: 'artists' });
266:   }
267:   for (const l of state.loans) {
268:     if (l.remaining > 0) items.push({ label: 'Loan payment', amount: l.payment, cat: 'loan' });
269:   }
270:   for (const wing of STUDIO_WINGS) {
271:     const lvl = state.complex?.wings?.[wing.id] || 0;
272:     if (lvl <= 0) continue;
273:     const info = wing.levels[clamp(lvl, 0, wing.levels.length - 1)];
274:     if (info?.upkeep) items.push({ label: `${wing.name} upkeep`, amount: info.upkeep, cat: 'complex' });
275:   }
276:   const discount = complexBonuses().officeDiscount;
277:   const office = Math.round((650 + state.tier * 900) * (1 - discount));
278:   items.push({ label: 'Office & admin', amount: office, cat: 'office' });
279:   return items;
280: }
