366: export function recordSong(payload = {}) {
367:   const artist = findRosterArtist(payload.artistId);
368:   if (!artist) return { error: 'Choose an artist.' };
369:   if (artist.busyUntil > state.week) return { error: `${artist.name} is on tour and can’t record this week.` };
370:   if (artist.onBreakUntil > state.week) return { error: `${artist.name} is on a career break until week ${artist.onBreakUntil}.` };
371:   const p = previewSong(payload);
372:   if (!p) return { error: 'Session could not be set up.' };
373:   if (state.cash < p.cost) return { error: `Not enough cash. Session costs ${fmtMoney(p.cost)}.` };
374:   const b = BUDGETS[payload.budget] || BUDGETS.standard;
375:   const f = FOCUS[payload.focus] || FOCUS.balanced;
376:   const producer = staffSkill('producer', payload.producerId);
377:   const writer = staffSkill('songwriter', payload.writerId);
378:   const feature = payload.featureId && payload.featureId !== 'none' ? findRosterArtist(payload.featureId) : null;
379:   const genre = payload.genre || artist.genre;
380:   const quality = clamp(p.quality + rand(-4, 4), 20, 99);
381:   const commercial = clamp(p.commercial + rand(-4, 4), 15, 99);
382:   const title = (payload.title || '').trim() || songTitle(genre);
383:   spend(p.cost, 'recording');
384:   const demo = {
385:     id: uid('demo'),
386:     title,
387:     artistId: artist.id,
388:     artistName: artist.name,
389:     genre,
390:     quality: Math.round(quality),
391:     commercial: Math.round(commercial),
392:     appeal: Math.round(quality * 0.56 + commercial * 0.44),
393:     focus: payload.focus || 'balanced',
394:     budget: payload.budget || 'standard',
395:     producerId: producer?.id || null,
396:     producerName: producer?.name || 'Self-produced',
397:     writerName: writer?.name || artist.name,
398:     featureId: feature?.id || null,
399:     featureName: feature?.name || null,
400:     studioId: payload.studioId,
401:     createdWeek: state.week,
402:     cost: p.cost,
403:     cover: { hue: randi(0, 360), style: randi(0, 4) },
404:   };
405:   state.demos.unshift(demo);
406:   artist.morale = clamp(artist.morale + 3, 0, 100);
407:   addNews(`${artist.name} finished a new ${b.name.toLowerCase()}-budget session: “${title}”.`, 'studio');
408:   saveGame();
409:   return { ok: true, demo };
410: }
