662:     id: uid('tour'),
663:     artistId: p.artist.id,
664:     artistName: p.artist.name,
665:     venueId: p.venue.id,
666:     venueName: p.venue.name,
667:     dates: p.dates,
668:     price: p.price,
669:     production: p.prod,
670:     marketing: p.marketing,
671:     showsPerWeek: 2,
