842: export function contractPackages(a) {
843:   if (!a) return [];
844:   const demand = a.salary || 1000;
845:   const legal = hasFacility('legal') ? 0.88 : 1;
846:   const mgmt = hasFacility('management') ? 0.94 : 1;
847:   const salary = (n) => Math.round((demand * n * mgmt) / 10) * 10;
848:   return [
849:     { id: 'budget', name: 'Budget Deal', advance: Math.round(a.advanceDemand * 0.55 * legal), salary: salary(0.82), royalty: Math.max(0.09, a.royaltyDemand - 0.04), weeks: 52, loyalty: -2, adj: -0.12, desc: 'Low risk, low commitment' },
850:     { id: 'standard', name: 'Standard Deal', advance: Math.round(a.advanceDemand * legal), salary: salary(1), royalty: a.royaltyDemand, weeks: 78, loyalty: 0, adj: 0.05, desc: 'A fair, balanced offer' },
851:     { id: 'star', name: 'Star Treatment', advance: Math.round(a.advanceDemand * 1.65 * legal), salary: salary(1.28), royalty: Math.min(0.3, a.royaltyDemand + 0.05), weeks: 104, loyalty: 8, adj: 0.24, desc: 'Big money, big loyalty' },
852:   ];
