854: export function signChance(a, pkg, rep = state.reputation) {
855:   let c = 0.18 + rep * 0.008 + (a.popularity < 25 ? 0.18 : a.popularity < 45 ? 0.04 : -0.08) - a.ego * 0.003 + pkg.adj + (a.loyalty - 50) * 0.001;
856:   if (state.facilities.includes('management')) c += 0.05;
857:   if (state.tier >= 3) c += 0.08;
858:   c += complexBonuses().sign;
859:   return clamp(c, 0.05, 0.96);
860: }
861: export function signArtist(artistId, packageId) {
862:   const a = state.prospects.find((x) => x.id === artistId);
863:   if (!a) return { error: 'This artist is no longer available.' };
864:   const pkg = contractPackages(a).find((p) => p.id === packageId);
865:   if (!pkg) return { error: 'Choose a contract package.' };
866:   if (state.cash < pkg.advance) return { error: `Advance of ${fmtMoney(pkg.advance)} is too large for your balance.` };
867:   const chanceVal = signChance(a, pkg);
868:   if (Math.random() > chanceVal) {
