417: export function scheduleRelease(payload = {}) {
418:   const artist = findRosterArtist(payload.artistId);
419:   if (!artist) return { error: 'Choose an artist.' };
420:   const ids = payload.demoIds || [];
421:   const type = payload.type || 'single';
422:   const def = RELEASE_TYPES[type];
423:   if (!def) return { error: 'Unknown release type.' };
424:   if (ids.length < def.min || ids.length > def.max) return { error: `${def.name} needs ${def.min === def.max ? def.min : `${def.min}–${def.max}`} songs.` };
425:   const demos = ids.map(findDemo).filter(Boolean);
426:   if (demos.length !== ids.length) return { error: 'One of those songs is no longer available.' };
427:   if (demos.some((d) => d.artistId !== artist.id)) return { error: 'All songs on a release must be by the same lead artist.' };
428:   if (artist.busyUntil > state.week) return { error: `${artist.name} is on tour. Schedule the release for after the tour.` };
429:   const offset = Number(payload.offset || 0);
430:   const marketing = Number(payload.marketing || 0);
431:   if (state.cash < marketing) return { error: `Not enough cash for the ${fmtMoney(marketing)} marketing budget.` };
432:   if (marketing > 0) spend(marketing, 'marketing');
433:   const release = {
434:     id: uid('rel'),
435:     type,
436:     title: (payload.title || '').trim() || (type === 'single' ? demos[0].title : albumTitle(demos[0].genre)),
437:     artistId: artist.id,
438:     artistName: artist.name,
439:     genre: demos[0].genre,
440:     demoIds: ids,
441:     trackIds: [],
442:     releaseWeek: state.week + offset,
443:     marketing,
444:     cover: computeTrackCover(demos[0].cover),
445:     createdWeek: state.week,
446:     status: offset === 0 ? 'launching' : 'scheduled',
447:     streams: 0,
448:     revenue: 0,
449:   };
450:   state.releases.unshift(release);
451:   for (const d of demos) d.releaseId = release.id;
452:   artist.morale = clamp(artist.morale + 3, 0, 100);
453:   artist.popularity = clamp(artist.popularity + 0.4, 0, 97);
454:   addNews(`${artist.name} announces ${def.name === 'Album' ? 'the album' : def.name === 'EP' ? 'an EP' : 'the single'} “${release.title}”${offset > 0 ? ` for week ${state.week + offset}` : ' — out now'}.`, 'release');
455:   if (offset === 0) launchRelease(release);
456:   saveGame();
457:   return { ok: true, release };
458: }
