464: function launchRelease(release) {
465:   if (!release || release.status === 'active' || release.status === 'cancelled') return;
466:   const artist = findRosterArtist(release.artistId);
467:   const dist = distById(state.dist);
468:   const trend = state.trends[release.genre] || 1;
469:   const created = [];
470:   for (const demoId of release.demoIds) {
471:     const demo = findDemo(demoId);
472:     if (!demo) continue;
473:     const appeal = demo.quality * 0.56 + demo.commercial * 0.44;
474:     const extra = releaseMarketingMult(release) * (artist ? (0.9 + artist.popularity / 260) : 1);
475:     const peak = computePeak(appeal, artist?.popularity || 30, state.reputation, dist.reach, extra, trend);
476:     const halfLife = 4 + demo.quality / 10 + (artist?.popularity || 30) / 50;
477:     const track = {
478:       id: uid('trk'),
479:       title: demo.title,
480:       artistId: demo.artistId,
481:       artistName: demo.artistName,
482:       artistPopularity: artist?.popularity || 30,
483:       labelId: 'player',
484:       labelName: state.label.name,
485:       labelColor: state.label.color,
486:       genre: demo.genre,
487:       quality: demo.quality,
488:       commercial: demo.commercial,
489:       appeal,
490:       releaseKey: release.id,
491:       releaseTitle: release.title,
492:       releaseType: release.type,
493:       releaseWeek: state.week,
494:       peak,
495:       halfLife,
496:       weekly: 0,
497:       lastWeekly: 0,
498:       streamsTotal: 0,
499:       revenue: 0,
500:       chartPeak: 0,
501:       chartWeeks: 0,
502:       lastPos: 0,
503:       isPlayer: true,
504:       cover: release.cover,
505:       featureName: demo.featureName,
506:       rightsSold: false,
507:       entered: false,
508:       hit10: false,
509:       hit1: false,
510:     };
511:     state.tracks.push(track);
512:     state.demos = state.demos.filter((d) => d.id !== demo.id);
513:     created.push(track.id);
514:     release.streams = release.streams || 0;
515:   }
516:   release.trackIds = created;
517:   release.status = 'active';
518:   release.launchWeek = state.week;
519:   if (created.length) {
520:     state.flags.releaseCount++;
521:     state.totals.releases++;
522:     addRep(0.5);
523:     addNews(`“${release.title}” by ${release.artistName} is out now across all platforms.`, 'release');
524:     if (artist) {
525:       artist.morale = clamp(artist.morale + 6, 0, 100);
526:       artist.popularity = clamp(artist.popularity + 0.8, 0, 97);
527:       artist.hits = (artist.hits || 0) + 1;
528:     }
529:     for (const id of created) maybeReleaseCollectible(findTrack(id));
530:   }
531: }
