553: export function startCampaign(payload = {}) {
554:   const def = campaignById(payload.type);
555:   if (!def) return { error: 'Unknown campaign.' };
556:   const targets = campaignTargets(def.id);
557:   const target = targets.find((t) => t.id === payload.targetId);
558:   if (!target) return { error: 'Choose a target for this campaign.' };
559:   const cost = def.cost;
560:   if (state.cash < cost) return { error: `Not enough cash. This campaign costs ${fmtMoney(cost)}.` };
561:   spend(cost, 'marketing');
562:   let mult = 1;
563:   let note = '';
564:   const boost = hasFacility('marketing') ? 1.18 : 1;
565:   if (def.id === 'playlist') mult = 0.26;
566:   if (def.id === 'radio') mult = 0.2;
567:   if (def.id === 'video') mult = 0.38;
568:   if (def.id === 'launch') mult = 0.55;
569:   if (def.id === 'billboard') mult = 0.12;
570:   if (def.id === 'viral') {
571:     const roll = Math.random();
572:     mult = roll < 0.22 ? 1.5 : roll < 0.62 ? 0.45 : 0.18;
573:     note = mult > 1 ? 'The clip is taking off!' : 'The stunt is getting modest traction.';
574:   }
575:   mult *= boost;
576:   const artistId = def.target === 'release' ? findRelease(target.id)?.artistId : target.id;
577:   const artist = findRosterArtist(artistId);
578:   const campaign = {
579:     id: uid('cmp'),
580:     type: def.id,
581:     name: def.name,
582:     targetId: target.id,
583:     targetName: target.name,
584:     artistId,
585:     releaseId: def.target === 'release' ? target.id : null,
586:     startWeek: state.week,
587:     endWeek: state.week + def.weeks - 1,
588:     mult: mult * (def.id === 'billboard' ? 0.12 : 1),
589:     cost,
590:     note,
591:   };
592:   if (def.id === 'social' && artist) {
593:     artist.popularity = clamp(artist.popularity + 1.2, 0, 97);
594:     artist.fans += Math.round(artist.fans * 0.04 + 8000);
595:     artist.morale = clamp(artist.morale + 2, 0, 100);
596:   }
597:   if (def.id === 'interview' && artist) {
598:     artist.popularity = clamp(artist.popularity + 1.6, 0, 97);
599:     artist.morale = clamp(artist.morale + 4, 0, 100);
600:   }
601:   state.campaigns.unshift(campaign);
602:   addNews(`${def.name} launched for ${target.name}${note ? ` — ${note}` : ''}.`, 'marketing');
603:   saveGame();
604:   return { ok: true, campaign };
605: }
