607: export function campaignMultiplier(track) {
608:   let m = 1;
609:   for (const c of activeCampaigns()) {
610:     if (c.type === 'social' || c.type === 'interview') continue;
611:     if (c.type === 'billboard') {
612:       if (c.artistId === track.artistId) m += c.mult * (hasFacility('marketing') ? 1.18 : 1);
613:       continue;
614:     }
615:     if (c.releaseId && c.releaseId === track.releaseKey) m += c.mult;
616:     else if (c.targetId === track.id) m += c.mult;
617:   }
618:   return m;
619: }
620: export function campaignRadioBonus(track) {
621:   let b = 0;
622:   for (const c of activeCampaigns()) {
623:     if (c.type === 'radio' && (c.releaseId === track.releaseKey || c.targetId === track.id)) b += 0.25;
624:   }
625:   return b;
626: }
