629: export function previewTour(o = {}) {
630:   const artist = findRosterArtist(o.artistId);
631:   const venue = venueById(o.venueId);
632:   if (!artist || !venue) return null;
633:   const dates = Number(o.dates || 8);
634:   const price = Number(o.price || venue.ticket);
635:   const prod = Number(o.production ?? 1);
636:   const marketing = Number(o.marketing || 0);
637:   const prodMult = [0.72, 1, 1.42][prod] || 1;
638:   const priceFactor = clamp(1 - (price / venue.ticket - 1) * 0.38, 0.55, 1.16);
639:   const demand = clamp(0.16 + artist.popularity / 100 * 0.92 + (marketing / 60000) * 0.1 + (prodMult - 1) * 0.05, 0.08, 1.05);
640:   const attendance = Math.round(venue.cap * demand * priceFactor);
641:   const grossPer = attendance * price * 0.9;
642:   const merch = hasFacility('merch') ? attendance * 7.5 : 0;
643:   const costPer = venue.cost * prodMult;
644:   const revenue = (grossPer + merch) * dates;
645:   const cost = costPer * dates + marketing;
646:   const weeks = Math.ceil(dates / 2);
647:   return {
648:     artist, venue, dates, price, prod, marketing, attendance,
649:     fill: clamp(demand * priceFactor, 0, 1.1), revenue, cost, profit: revenue - cost,
650:     weeks, perShow: grossPer + merch, costPerShow: costPer,
651:     priceFactor,
652:   };
653: }
654: export function planTour(o = {}) {
