656:   if (!p) return { error: 'Tour details are incomplete.' };
657:   if (p.artist.popularity < p.venue.minPop) return { error: `${p.artist.name} needs ${p.venue.minPop} popularity for ${p.venue.name} (currently ${p.artist.popularity.toFixed(0)}).` };
658:   if (p.artist.busyUntil > state.week) return { error: `${p.artist.name} is already on tour.` };
659:   if (state.cash < p.marketing) return { error: 'Not enough cash for the tour marketing budget.' };
660:   if (p.marketing > 0) spend(p.marketing, 'touring');
661:   const tour = {
662:     id: uid('tour'),
663:     artistId: p.artist.id,
664:     artistName: p.artist.name,
665:     venueId: p.venue.id,
666:     venueName: p.venue.name,
667:     dates: p.dates,
668:     price: p.price,
669:     production: p.prod,
670:     marketing: p.marketing,
671:     showsPerWeek: 2,
672:     weeks: p.weeks,
673:     weeksDone: 0,
674:     showsDone: 0,
675:     attendanceTotal: 0,
676:     revenueTotal: 0,
677:     costTotal: 0,
