850:     { id: 'standard', name: 'Standard Deal', advance: Math.round(a.advanceDemand * legal), salary: salary(1), royalty: a.royaltyDemand, weeks: 78, loyalty: 0, adj: 0.05, desc: 'A fair, balanced offer' },
851:     { id: 'star', name: 'Star Treatment', advance: Math.round(a.advanceDemand * 1.65 * legal), salary: salary(1.28), royalty: Math.min(0.3, a.royaltyDemand + 0.05), weeks: 104, loyalty: 8, adj: 0.24, desc: 'Big money, big loyalty' },
