854: export function signChance(a, pkg, rep = state.reputation) {
855:   let c = 0.18 + rep * 0.008 + (a.popularity < 25 ? 0.18 : a.popularity < 45 ? 0.04 : -0.08) - a.ego * 0.003 + pkg.adj + (a.loyalty - 50) * 0.001;
856:   if (state.facilities.includes('management')) c += 0.05;
857:   if (state.tier >= 3) c += 0.08;
858:   c += complexBonuses().sign;
