970: function weeklyStreams(track, age) {
971:   const radio = campaignRadioBonus(track);
972:   const hl = track.halfLife * (1 + radio);
973:   const base = age <= 0 ? track.peak * 0.58 : track.peak * Math.pow(0.5, Math.max(0, age - 1) / hl) + track.peak * 0.012;
974:   const prev = state.prevSongs.find((p) => p.id === track.id);
975:   const chartBoost = prev ? 1 + Math.max(0, 41 - prev.pos) / 40 * 0.22 : 1;
976:   const trend = state.trends[track.genre] || 1;
977:   return Math.max(0, base * chartBoost * trackActivityFor(track) * rand(0.9, 1.1) * (0.85 + trend * 0.15));
978: }
