980: function simulateTracks() {
981:   const artistStreams = new Map();
982:   for (const track of state.tracks) {
983:     const age = state.week - track.releaseWeek;
984:     if (age < 0) continue;
985:     const weekly = weeklyStreams(track, age);
986:     track.lastWeekly = track.weekly || 0;
987:     track.weekly = weekly;
988:     track.streamsTotal = (track.streamsTotal || 0) + weekly;
989:     if (track.isPlayer) {
990:       const dist = distById(state.dist);
991:       const artist = findRosterArtist(track.artistId);
992:       const royaltyRate = artist?.contract?.royalty ?? 0.15;
993:       const gross = weekly * 0.0046;
994:       const sales = weekly * 0.00055 * 1.29;
995:       let net = gross * (1 - dist.fee) * (1 - royaltyRate) + sales * (1 - dist.fee) * 0.7;
996:       if (track.rightsSold) net = 0;
997:       if (hasFacility('publishing')) net *= 1.04;
998:       earn(net, 'streaming');
999:       track.revenue = (track.revenue || 0) + net;
1000:       state.totals.streams += weekly;
1001:       state.totals.downloads += weekly * 0.00055;
1002:       if (artist) {
1003:         artistStreams.set(track.artistId, (artistStreams.get(track.artistId) || 0) + weekly);
1004:         artist.totalStreams = (artist.totalStreams || 0) + weekly;
1005:         artist.fans += Math.round(weekly * 0.012);
1006:         state.totals.fans = Math.round((state.totals.fans || 0) + weekly * 0.012);
1007:       }
1008:       if (!track.rightsSold && weekly > 60000 && chance(0.004 + (track.quality / 100) * 0.008 + (hasFacility('sync') ? 0.02 : 0))) {
1009:         const amount = Math.round(rand(4000, 24000) + track.quality * 260);
1010:         earn(amount, 'sync');
1011:         addNews(`“${track.title}” licensed for a sync placement — ${fmtMoney(amount)}.`, 'finance');
1012:       }
1013:       if (hasFacility('merch')) {
1014:         const merch = weekly * 0.00009 * 26;
1015:         earn(merch, 'merch');
1016:       }
1017:       track.chartEligible = age <= 30;
1018:     }
1019:   }
1020:   // Artist popularity grows from actual listening.
1021:   for (const a of state.roster) {
1022:     const s = artistStreams.get(a.id) || 0;
1023:     if (s > 0) {
1024:       const delta = clamp(Math.log10(s / 35000 + 1) * 0.72, 0.02, 2.2);
