324: export function previewSong(o = {}) {
325:   const artist = findRosterArtist(o.artistId) || {};
326:   if (!artist.id) return null;
327:   const producer = staffSkill('producer', o.producerId);
328:   const writer = staffSkill('songwriter', o.writerId);
329:   const feature = o.featureId && o.featureId !== 'none' ? findRosterArtist(o.featureId) : null;
330:   const studio = state.studios.find((s) => s.id === o.studioId) || state.studios[0];
331:   const b = BUDGETS[o.budget] || BUDGETS.standard;
332:   const f = FOCUS[o.focus] || FOCUS.balanced;
333:   const trait = traitById(artist.trait) || {};
334:   const genre = o.genre || artist.genre;
335:   const trend = state.trends[genre] || 1;
336:   const producerSkillVal = producer ? producer.skill : artist.skill * 0.65;
337:   const writerSkillVal = writer ? writer.skill : artist.songwriting;
338:   const studioQ = studioQuality(studio?.id);
339:   const genreMatch = artist.genre === genre ? 1 : 0;
340:   const cx = complexBonuses();
341:   let quality = 18 + artist.skill * 0.26 + writerSkillVal * 0.19 + producerSkillVal * 0.2
342:     + (studioQ - 20) * 0.13 + b.quality * 0.7 + (trait.quality || 0) + f.quality
343:     + genreMatch * 4 + (feature ? (feature.skill - 50) * 0.08 + 1.5 : 0) + cx.quality
344:     + (artist.creativeBoost > state.week ? 2.5 : 0);
345:   let commercial = 15 + artist.charisma * 0.32 + quality * 0.22 + (trend - 1) * 26 + f.commercial
346:     + (trait.commercial || 0) + genreMatch * 2 + (feature ? feature.charisma * 0.08 : 0)
347:     + (artist.commercialBoost > state.week ? 3 : 0);
348:   const featMod = (artist.popularity + (feature?.popularity || 0)) / 220;
349:   quality = clamp(quality + featMod * 3, 20, 99);
350:   commercial = clamp(commercial, 15, 99);
351:   const appeal = quality * 0.56 + commercial * 0.44;
352:   const peak = computePeak(appeal, artist.popularity, state.reputation, distById(state.dist).reach, 1, trend, false);
353:   const featureFee = feature ? Math.round(2500 + feature.popularity * 190) : 0;
354:   const legal = hasFacility('legal') ? 0.88 : 1;
355:   const cost = Math.round((b.cost + featureFee) * legal * cx.costMult);
356:   return { quality: Math.round(quality), commercial: Math.round(commercial), appeal: Math.round(appeal), peak, cost, featureFee, studioQ: Math.round(studioQ) };
357: }
