561:   spend(cost, 'marketing');
562:   let mult = 1;
563:   let note = '';
564:   const boost = hasFacility('marketing') ? 1.18 : 1;
565:   if (def.id === 'playlist') mult = 0.26;
566:   if (def.id === 'radio') mult = 0.2;
567:   if (def.id === 'video') mult = 0.38;
568:   if (def.id === 'launch') mult = 0.55;
569:   if (def.id === 'billboard') mult = 0.12;
570:   if (def.id === 'viral') {
571:     const roll = Math.random();
572:     mult = roll < 0.22 ? 1.5 : roll < 0.62 ? 0.45 : 0.18;
573:     note = mult > 1 ? 'The clip is taking off!' : 'The stunt is getting modest traction.';
574:   }
575:   mult *= boost;
