691:     const venue = venueById(tour.venueId);
692:     if (!artist || !venue) { tour.status = 'cancelled'; continue; }
693:     const remaining = tour.dates - tour.showsDone;
694:     const shows = Math.min(tour.showsPerWeek, remaining);
695:     if (shows <= 0) continue;
696:     const prodMult = [0.72, 1, 1.42][tour.production] || 1;
697:     const priceFactor = clamp(1 - (tour.price / venue.ticket - 1) * 0.38, 0.55, 1.16);
698:     const demand = clamp(0.16 + artist.popularity / 100 * 0.92 + (tour.marketing / 60000) * 0.1, 0.08, 1.05);
699:     const attendance = Math.round(venue.cap * demand * priceFactor * rand(0.92, 1.06));
700:     const gross = attendance * tour.price * 0.9;
701:     const merch = hasFacility('merch') ? attendance * 7.5 : 0;
702:     const cost = venue.cost * prodMult;
703:     const revenue = (gross + merch) * shows;
704:     const totalCost = cost * shows;
705:     earn(revenue, 'touring');
706:     spend(totalCost, 'touring');
707:     state.totals.tourRevenue += revenue;
708:     tour.weeksDone++;
709:     tour.showsDone += shows;
710:     tour.attendanceTotal += attendance * shows;
711:     tour.revenueTotal += revenue;
712:     tour.costTotal += totalCost;
713:     artist.popularity = clamp(artist.popularity + 0.5, 0, 97);
714:     artist.morale = clamp(artist.morale + 1, 0, 100);
715:     if (tour.showsDone >= tour.dates) {
716:       tour.status = 'complete';
