723:       artist.busyUntil = state.week;
724:       addNews(`${artist.name} wrapped the ${tour.venueName} tour — ${fmtNum(tour.attendanceTotal)} tickets sold, ${fmtMoney(profit)} ${profit >= 0 ? 'profit' : 'loss'}.`, 'tour');
725:       if (chance(0.72)) addCollectible(pick(['poster', 'backstage', 'signed_vinyl']), { artistName: artist.name, artistId: artist.id, note: `${tour.venueName} tour` });
726:       if (profit > 250000 && chance(0.35)) addCollectible('guitar', { artistName: artist.name, artistId: artist.id, note: 'Stage-used on a sell-out run' });
