143:   [...root.children].forEach((el) => { if (el.textContent === msg) el.remove(); });
144:   const el = document.createElement('div');
145:   el.className = `toast ${kind}`;
146:   el.textContent = msg;
147:   root.appendChild(el);
148:   setTimeout(() => { el.classList.add('out'); setTimeout(() => el.remove(), 240); }, ms);
149: }
