200: function sparkline(values, w = 130, h = 34, color = 'var(--brand)', fill = true) {
201:   if (!values || values.length < 2) values = [0, 0, 0];
202:   const max = Math.max(...values, 1);
203:   const min = Math.min(...values, 0);
204:   const range = max - min || 1;
205:   const pts = values.map((v, i) => [((i / (values.length - 1)) * w).toFixed(1), (h - ((v - min) / range) * (h - 4) - 2).toFixed(1)]);
206:   const line = pts.map((p) => p.join(',')).join(' ');
207:   const id = `sp${Math.random().toString(36).slice(2, 7)}`;
208:   return `<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" style="overflow:visible">
209:     ${fill ? `<defs><linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${color}" stop-opacity=".28"/><stop offset="1" stop-color="${color}" stop-opacity="0"/></linearGradient></defs><polygon points="0,${h} ${line} ${w},${h}" fill="url(#${id})"/>` : ''}
210:     <polyline points="${line}" fill="none" stroke="${color}" stroke-width="1.8" stroke-linejoin="round" stroke-linecap="round"/>
211:   </svg>`;
212: }
