246:     if (t.closest('#song-form')) updateSongPreview();
247:     if (t.closest('#tour-form')) updateTourPreview();
248:     if (t.id === 'release-marketing') {
249:       const out = document.getElementById('release-marketing-out');
250:       if (out) out.textContent = money(Number(t.value));
251:     }
252:   });
253:   document.addEventListener('change', (e) => {
254:     const t = e.target;
255:     if (t.dataset.act) { handleAction(t.dataset.act, t); return; }
256:     if (t.closest('#song-form')) updateSongPreview();
257:     if (t.closest('#tour-form')) updateTourPreview();
258:     if (t.dataset.field === 'type' && t.closest('#release-form')) {
