156:       close: { yaw: 0.9, pitch: 0.2, distance: 8.4, targetY: 1.7 },
157:       orbit: { yaw: 2.2, pitch: 0.32, distance: 12, targetY: 1.7 },
158:       grounds: { yaw: 0.34, pitch: 0.28, distance: 18.5, targetY: 2.1 },
159:     };
160:     const p = presets[name] || presets.wide;
161:     this.yaw = p.yaw;
162:     this.pitch = p.pitch;
163:     this.distance = p.distance;
164:     this.targetY = p.targetY;
165:     this.lastInteract = performance.now();
166:   }
167: 
168:   project(x, y, z) {
169:     const cy = Math.cos(this.yaw), sy = Math.sin(this.yaw);
170:     const cp = Math.cos(this.pitch), sp = Math.sin(this.pitch);
171:     const x1 = x * cy + z * sy;
172:     const z1 = -x * sy + z * cy;
173:     const y1 = (y - this.targetY) * cp - z1 * sp;
174:     const z2 = (y - this.targetY) * sp + z1 * cp;
175:     const depth = this.distance / this.zoom - z2;
176:     if (depth < 0.55) return null;
177:     const s = this.focal / depth;
178:     return { x: this.cx + x1 * s, y: this.cy - y1 * s, d: depth, s };
179:   }
180: 
181:   poly(points, color, opts = {}) {
182:     const projected = points.map((p) => this.project(p[0], p[1], p[2]));
183:     if (projected.some((p) => !p)) return;
184:     const depth = opts.far ? 9999 : projected.reduce((a, p) => a + p.d, 0) / projected.length;
185:     this.items.push({ type: 'poly', pts: projected, depth, color, alpha: opts.alpha ?? 1, stroke: opts.stroke, lw: opts.lw || 1, glow: opts.glow });
186:   }
187: 
188:   line(a, b, color, opts = {}) {
189:     const p1 = this.project(a[0], a[1], a[2]);
190:     const p2 = this.project(b[0], b[1], b[2]);
191:     if (!p1 || !p2) return;
192:     this.items.push({ type: 'line', p1, p2, depth: (p1.d + p2.d) / 2 - 0.01, color, alpha: opts.alpha ?? 1, lw: opts.lw || 1 });
193:   }
194: 
195:   label(text, x, y, z, opts = {}) {
196:     const p = this.project(x, y, z);
197:     if (!p) return;
198:     this.items.push({ type: 'text', p, depth: p.d - 0.02, text, color: opts.color || '#fff', size: opts.size || 11, weight: opts.weight || 800, alpha: opts.alpha ?? 1, align: opts.align || 'center' });
199:   }
200: 
201:   sphere(x, y, z, r, color, opts = {}) {
202:     const p = this.project(x, y, z);
203:     if (!p) return;
204:     this.items.push({ type: 'sphere', p, radius: Math.max(0.6, r * p.s), color, alpha: opts.alpha ?? 1, depth: p.d, glow: opts.glow });
205:   }
206: 
207:   glow(x, y, z, r, color, alpha = 0.35) {
208:     const p = this.project(x, y, z);
209:     if (!p) return;
210:     this.items.push({ type: 'glow', p, radius: Math.max(4, r * p.s), color, alpha, depth: p.d + 0.01 });
211:   }
212: 
213:   box(cx, cy, cz, sx, sy, sz, color, opts = {}) {
214:     const x0 = cx - sx / 2, x1 = cx + sx / 2;
215:     const y0 = cy - sy / 2, y1 = cy + sy / 2;
216:     const z0 = cz - sz / 2, z1 = cz + sz / 2;
217:     const c = hexToRgb(color);
218:     const a = opts.alpha ?? 1;
219:     const top = opts.top || 1.24;
220:     const fo = { far: opts.far };
221:     this.poly([[x0, y1, z0], [x1, y1, z0], [x1, y1, z1], [x0, y1, z1]], shade(c, top, a), fo);
222:     this.poly([[x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1]], shade(c, 0.96, a), fo);
223:     this.poly([[x1, y0, z1], [x1, y0, z0], [x1, y1, z0], [x1, y1, z1]], shade(c, 0.78, a), fo);
224:     this.poly([[x0, y0, z0], [x1, y0, z0], [x1, y1, z0], [x0, y1, z0]], shade(c, 0.58, a), fo);
225:     this.poly([[x0, y0, z0], [x0, y0, z1], [x0, y1, z1], [x0, y1, z0]], shade(c, 0.68, a), fo);
226:     if (opts.stroke) {
227:       const edge = opts.stroke;
228:       const pts = [[x0, y0, z0], [x1, y0, z0], [x1, y1, z0], [x0, y1, z0], [x0, y1, z1], [x1, y1, z1], [x1, y0, z1], [x0, y0, z1]];
229:       for (let i = 0; i < 4; i++) this.line(pts[i], pts[(i + 1) % 4], edge, { lw: 0.8, alpha: 0.6 });
230:       for (let i = 4; i < 8; i++) this.line(pts[i], pts[4 + ((i - 3) % 4)], edge, { lw: 0.8, alpha: 0.6 });
231:       this.line([x0, y0, z0], [x0, y1, z0], edge, { lw: 0.8, alpha: 0.6 });
232:       this.line([x1, y0, z0], [x1, y1, z0], edge, { lw: 0.8, alpha: 0.6 });
233:       this.line([x0, y0, z1], [x0, y1, z1], edge, { lw: 0.8, alpha: 0.6 });
234:       this.line([x1, y0, z1], [x1, y1, z1], edge, { lw: 0.8, alpha: 0.6 });
235:     }
236:   }
237: 
238:   cyl(cx, cy, cz, r, h, color, opts = {}) {
239:     const seg = opts.seg || 14;
240:     const c = hexToRgb(color);
241:     const y0 = cy, y1 = cy + h;
242:     for (let i = 0; i < seg; i++) {
243:       const a0 = (i / seg) * TAU, a1 = ((i + 1) / seg) * TAU;
244:       const x0 = cx + Math.cos(a0) * r, z0 = cz + Math.sin(a0) * r;
245:       const x1 = cx + Math.cos(a1) * r, z1 = cz + Math.sin(a1) * r;
246:       const f = 0.64 + 0.28 * (0.5 + 0.5 * Math.cos(a0 - this.yaw + Math.PI * 0.3));
247:       this.poly([[x0, y0, z0], [x1, y0, z1], [x1, y1, z1], [x0, y1, z0]], shade(c, f, opts.alpha ?? 1));
248:     }
249:     const top = [];
250:     for (let i = 0; i < seg; i++) {
251:       const a = (i / seg) * TAU;
252:       top.push([cx + Math.cos(a) * r, y1, cz + Math.sin(a) * r]);
253:     }
254:     this.poly(top, shade(c, 1.26, opts.alpha ?? 1));
255:     if (opts.glow) this.glow(cx, y1, cz, r * 2.4, color, 0.22);
256:   }
257: 
258:   floorPlane(w, d, color, opts = {}) {
259:     this.poly([[-w / 2, 0, -d / 2], [w / 2, 0, -d / 2], [w / 2, 0, d / 2], [-w / 2, 0, d / 2]], shade(hexToRgb(color), 1.22, opts.alpha ?? 1), { far: true });
260:     const grid = opts.grid ?? 1;
261:     if (grid) {
262:       const step = opts.step || 1.5;
263:       for (let x = -w / 2; x <= w / 2 + 0.01; x += step) this.line([x, 0.01, -d / 2], [x, 0.01, d / 2], '#ffffff', { lw: 0.5, alpha: 0.05 });
264:       for (let z = -d / 2; z <= d / 2 + 0.01; z += step) this.line([-w / 2, 0.01, z], [w / 2, 0.01, z], '#ffffff', { lw: 0.5, alpha: 0.05 });
265:     }
266:   }
267: 
268:   wall(w, h, z, color, opts = {}) {
269:     this.poly([[-w / 2, 0, z], [w / 2, 0, z], [w / 2, h, z], [-w / 2, h, z]], shade(hexToRgb(color), 1.28, opts.alpha ?? 1), { far: opts.far !== false });
270:     const panels = opts.panels ?? 0;
271:     for (let i = 0; i < panels; i++) {
272:       const x = -w / 2 + (i + 0.5) * (w / panels);
273:       this.box(x, h * 0.55, z + 0.08, w / panels * 0.72, h * 0.42, 0.08, '#2c2439');
274:       this.box(x, h * 0.55, z + 0.13, w / panels * 0.6, h * 0.32, 0.03, '#3b3050');
275:     }
276:     if (opts.cove !== false) {
277:       this.line([-w / 2, h - 0.06, z + 0.16], [w / 2, h - 0.06, z + 0.16], css(this.accent, 0.5), { lw: 1.6 });
278:       this.glow(0, h - 0.3, z + 0.4, w * 0.46, css(this.accent), 0.1);
279:     }
280:   }
281: 
282:   spot(x, y, z, radius, color, alpha = 0.18) {
283:     const p = this.project(x, y, z);
284:     if (!p) return;
285:     this.items.push({ type: 'spot', p, radius: radius * p.s, color, alpha, depth: p.d - 2 });
286:   }
287: 
288:   build() {
289:     this.items = [];
290:     const builders = { studio: studioScene, office: officeScene, hall: hallScene, awards: awardsScene, festival: festivalScene };
291:     (builders[this.kind] || studioScene)(this);
292:     this.items.sort((a, b) => b.depth - a.depth);
293:   }
294: 
295:   render() {
296:     const ctx = this.ctx;
297:     ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
298:     const g = ctx.createLinearGradient(0, 0, 0, this.h);
299:     const darkTop = mix(this.wallColor.map((c) => c * 0.9), [10, 9, 18], 0.35);
300:     const base = this.kind === 'festival' ? [6, 7, 16] : this.kind === 'awards' ? [8, 6, 20] : this.kind === 'hall' ? [12, 9, 8] : [6, 7, 12];
301:     g.addColorStop(0, css(darkTop));
302:     g.addColorStop(1, css(base));
303:     ctx.fillStyle = g;
304:     ctx.fillRect(0, 0, this.w, this.h);
305:     // ambient glow behind the set
306:     const rg = ctx.createRadialGradient(this.w * 0.5, this.h * 0.42, 2, this.w * 0.5, this.h * 0.42, this.w * 0.52);
307:     rg.addColorStop(0, css(this.accent, this.kind === 'festival' ? 0.2 : 0.13));
308:     rg.addColorStop(1, css(this.accent, 0));
309:     ctx.fillStyle = rg;
310:     ctx.fillRect(0, 0, this.w, this.h);
311:     this.build();
312:     for (const it of this.items) {
313:       if (it.type === 'poly') {
314:         ctx.beginPath();
315:         it.pts.forEach((p, i) => (i ? ctx.lineTo(p.x, p.y) : ctx.moveTo(p.x, p.y)));
316:         ctx.closePath();
317:         ctx.globalAlpha = it.alpha;
318:         ctx.fillStyle = it.color;
319:         if (it.glow) { ctx.shadowColor = it.glow; ctx.shadowBlur = 14; }
320:         ctx.fill();
321:         ctx.shadowBlur = 0;
322:         if (it.stroke) { ctx.strokeStyle = it.stroke; ctx.lineWidth = it.lw; ctx.stroke(); }
323:       } else if (it.type === 'line') {
324:         ctx.globalAlpha = it.alpha;
325:         ctx.strokeStyle = it.color;
326:         ctx.lineWidth = it.lw;
327:         ctx.beginPath(); ctx.moveTo(it.p1.x, it.p1.y); ctx.lineTo(it.p2.x, it.p2.y); ctx.stroke();
328:       } else if (it.type === 'sphere') {
329:         ctx.globalAlpha = it.alpha;
330:         const c = hexToRgb(it.color);
331:         const gr = ctx.createRadialGradient(it.p.x - it.radius * 0.3, it.p.y - it.radius * 0.35, it.radius * 0.1, it.p.x, it.p.y, it.radius);
332:         gr.addColorStop(0, css(mix(c, [255, 255, 255], 0.55)));
333:         gr.addColorStop(0.5, css(c));
334:         gr.addColorStop(1, css(c.map((x) => x * 0.32)));
335:         ctx.fillStyle = gr;
336:         if (it.glow) { ctx.shadowColor = it.color; ctx.shadowBlur = 18; }
337:         ctx.beginPath(); ctx.arc(it.p.x, it.p.y, it.radius, 0, TAU); ctx.fill();
338:         ctx.shadowBlur = 0;
339:       } else if (it.type === 'glow') {
340:         const c = hexToRgb(it.color);
341:         const gr = ctx.createRadialGradient(it.p.x, it.p.y, 1, it.p.x, it.p.y, it.radius);
342:         gr.addColorStop(0, css(c, it.alpha));
343:         gr.addColorStop(1, css(c, 0));
344:         ctx.globalAlpha = 1;
345:         ctx.fillStyle = gr;
346:         ctx.fillRect(it.p.x - it.radius, it.p.y - it.radius, it.radius * 2, it.radius * 2);
347:       } else if (it.type === 'spot') {
348:         const c = hexToRgb(it.color);
349:         const gr = ctx.createRadialGradient(it.p.x, it.p.y, 1, it.p.x, it.p.y, it.radius);
350:         gr.addColorStop(0, css(c, it.alpha));
351:         gr.addColorStop(1, css(c, 0));
352:         ctx.globalAlpha = 1;
353:         ctx.fillStyle = gr;
354:         ctx.beginPath(); ctx.ellipse(it.p.x, it.p.y, it.radius, it.radius * 0.72, 0, 0, TAU); ctx.fill();
355:       } else if (it.type === 'text') {
356:         ctx.globalAlpha = it.alpha;
357:         ctx.fillStyle = it.color;
358:         ctx.font = `${it.weight} ${it.size}px ui-sans-serif, -apple-system, "Segoe UI", sans-serif`;
359:         ctx.textAlign = it.align;
360:         ctx.textBaseline = 'middle';
361:         if (it.depth < 30) { ctx.shadowColor = 'rgba(0,0,0,.65)'; ctx.shadowBlur = 6; }
362:         ctx.fillText(it.text, it.p.x, it.p.y);
363:         ctx.shadowBlur = 0;
364:       }
365:     }
366:     ctx.globalAlpha = 1;
367:   }
368: }
